function initNovalnetScript(){if($("#nn_cc_payment_id").length>0){var e=$("#nn_cc_payment_id").val(),n=$("#nn_logos").val().split("&"),t=$("#payment"+e).next().children("img").attr("class");$("#payment"+e).next().find("img").remove();for(var i=0,a=n.length;i<a;i++){var d=n[i].split("="),l='<img src="'+decodeURIComponent(d[1])+'" class="'+t+'" alt="'+$("#nn_logo_alt").val()+'" hspace="1">';$("#payment"+e).next().children("span").before(l)}}if(jQuery("input[name*='nn_display_testmode']").length>0)jQuery("input[name*='nn_display_testmode']").map((function(){if((e=jQuery(this).attr("id"))&&""!=jQuery('[id="'+e+'"]').val()){if(e.indexOf("novalnetkreditdebitkarte")>-1){var e=e.replace("novalnetkreditdebitkarte","novalnetkredit");jQuery('div[id="'+e+'"]').children().children().next().children("span").before("<span id=nn_testmode_"+e+" class=novalnet_test_mode>"+jQuery("#nn_testmode_text").val()+"</span>")}0==jQuery('[id="nn_testmode_'+e+'"]').length&&(jQuery('div[id="'+e+'"]').find(".novalnet_test_mode").remove(),jQuery('div[id="'+e+'"]').children().children().next().children("span").before("<span id=nn_testmode_"+e+" class=novalnet_test_mode>"+jQuery("#nn_testmode_text").val()+"</span>"))}})).get()}jQuery(document).ready((function(){initNovalnetScript()})),$(document).ajaxComplete((function(e,n,t){t.url.includes("Checkout")&&initNovalnetScript()}));